class Solution {
public:
    vector<int> finalPrices(vector<int>& prices) {
        vector<int> res = prices;
        vector<int> st;
        for (int i = 0; i < (int)prices.size(); i++) {
            while (!st.empty() && prices[st.back()] >= prices[i]) {
                res[st.back()] -= prices[i];
                st.pop_back();
            }
            st.push_back(i);
        }
        return res;
    }
};

class Solution {
    public int[] finalPrices(int[] prices) {
        int[] res = prices.clone();
        int[] st = new int[prices.length];
        int top = 0;
        for (int i = 0; i < prices.length; i++) {
            while (top > 0 && prices[st[top - 1]] >= prices[i]) {
                res[st[--top]] -= prices[i];
            }
            st[top++] = i;
        }
        return res;
    }
}

var finalPrices = function(prices) {
    const res = [...prices];
    const st = [];
    for (let i = 0; i < prices.length; i++) {
        while (st.length > 0 && prices[st[st.length - 1]] >= prices[i]) {
            res[st.pop()] -= prices[i];
        }
        st.push(i);
    }
    return res;
};
